from typing import List


def separate_paren_groups(paren_string: str) -> List[str]:
    result = []
    current_group = ""
    balance = 0

    for char in paren_string:
        if char == ' ':
            continue

        if char == '(':
            balance += 1
            current_group += char
        elif char == ')':
            balance -= 1
            current_group += char

        # If balance returns to 0, we've closed the outermost parenthesis of the current group
        if balance == 0 and current_group:
            result.append(current_group)
            current_group = ""

    return result

